        let errors = validate_config(&config);
        assert!(errors.iter().any(|e| e.rule == "invalid-var-name"));
    }

    #[test]
    fn validates_var_name_starting_with_digit() {
        let mut config = BivvyConfig::default();
        config.vars.insert(
