172	/// and `env`, plus the parent process environment, are layered on top of this
173	/// inside the step executor — the process env always wins.
174	///
175	/// If the named workflow does not exist in the config, only the global layers
176	/// are included.
177	///
178	/// # Errors
179	///
180	/// Returns an error if any specified env_file cannot be read or parsed.
181	pub fn build_yaml_env_stack(
182	    config: &BivvyConfig,
183	    workflow_name: &str,
184	    project_root: &Path,
185	) -> Result<EnvLayerStack> {
186	    let mut stack = EnvLayerStack::new();
187	
188	    if let Some(ref env_file) = config.settings.env_vars.env_file {
189	        let resolved = project_root.join(env_file);
190	        let file_env = load_env_file(&resolved)?;
191	        let mut layer = EnvLayer::new("settings.env_vars.env_file");
192	        for (k, v) in file_env {
193	            layer.set(k, v);
194	        }
195	        stack.push(layer);
196	    }
197	
198	    if !config.settings.env_vars.env.is_empty() {
199	        let mut layer = EnvLayer::new("settings.env_vars.env");
200	        for (k, v) in &config.settings.env_vars.env {
201	            layer.set(k, v);
202	        }
203	        stack.push(layer);
204	    }
205	
206	    if let Some(workflow) = config.workflows.get(workflow_name) {
207	        if let Some(ref env_file) = workflow.env_file {
208	            let resolved = project_root.join(env_file);
209	            let file_env = load_env_file(&resolved)?;
210	            let mut layer = EnvLayer::new(format!("workflows.{}.env_file", workflow_name));
