        let mut stack = EnvLayerStack::new();

        let mut base = EnvLayer::new("base");
        base.set("KEY", "base");
        stack.push(base);

        let mut local = EnvLayer::new("local");
        local.set("KEY", "override");
        stack.push(local);

        assert_eq!(stack.get("KEY"), Some("override"));
