            );
            let stack = build_yaml_env_stack(&config, "default", temp.path()).unwrap();
            assert_eq!(stack.get("PORT"), Some("9090"));
            assert_eq!(stack.source_of("PORT"), Some("settings.env_vars.env"));
        }

